package cn.zhuatech.modelgateway.controller;import cn.zhuatech.modelgateway.common.ApiResponse;import cn.zhuatech.modelgateway.model.GatewayAudit;import cn.zhuatech.modelgateway.service.ModelGatewayService;import jakarta.validation.Valid;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController@RequestMapping("/api/model-gateway")public class ModelGatewayController{private final ModelGatewayService service;public ModelGatewayController(ModelGatewayService s){service=s;}@PostMapping("/route")@PreAuthorize("hasAnyRole('ADMIN','OPERATOR')")public ApiResponse<ModelGatewayService.RouteResult>route(@Valid@RequestBody ModelGatewayService.RouteRequest r,Authentication a){return ApiResponse.ok("模型路由完成",service.route(r,a.getName()));}@GetMapping("/audits")@PreAuthorize("hasAnyRole('ADMIN','AUDITOR')")public ApiResponse<List<GatewayAudit>>audits(){return ApiResponse.ok("审计查询成功",service.audits());}}
